// Extraction et nettoyage.
// Conserve impérativement l'URL de la source : une opportunité sans source
// ne doit jamais être écrite en base.
return items.map((item) => ({
  json: {
    name: (item.json.title || '').trim(),
    description: (item.json.contentSnippet || '').trim(),
    source_url: item.json.link,
    source_name: 'À renseigner',
    fetched_at: new Date().toISOString(),
  },
}));

// Classification IA : catégorie, pays éligibles, types de projet, montants, date limite.
// Sortie systématiquement au statut UNVERIFIED : une validation humaine reste requise.
return items.map((item) => ({
  json: { ...item.json, status: 'UNVERIFIED', is_demo: false },
}));
